with latest as (select * from employees qualify row_number() over (partition by manager_id order by salary desc, id) = 1) select dept_id, level, count_if(job_title = 'Manager') as manager_events, count_if(job_title = 'Manager') as manager_events_2, approx_percentile(salary, array(0.25, 0.5, 0.75)) as salary_quartiles, grouping(dept_id) as grouping_level from latest group by grouping sets ((dept_id, level), (dept_id)) order by level nulls last
